using UnityEngine;using UnityEditor;
public static class ImportWeaponAudio{public static object Run(){AssetDatabase.Refresh();foreach(var name in new[]{"point","pierce","bleed","sweep","enso","resonance"}){string p="Assets/BokumyakuPrototype/Resources/BokumyakuAudio/sfx_attack_"+name+".wav";var i=(AudioImporter)AssetImporter.GetAtPath(p);var s=i.defaultSampleSettings;s.loadType=AudioClipLoadType.DecompressOnLoad;s.compressionFormat=AudioCompressionFormat.PCM;s.sampleRateSetting=AudioSampleRateSetting.PreserveSampleRate;i.defaultSampleSettings=s;i.forceToMono=false;i.loadInBackground=false;i.SaveAndReimport();}return "6 PCM weapon clips imported";}}
